'use client';

import {
  AuthProvider,
  OpenfortProvider,
  RecoveryMethod,
} from '@openfort/react';
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { useEffect, type ReactNode } from 'react';
import { base, baseSepolia } from 'viem/chains';
import { createConfig, WagmiProvider } from 'wagmi';
import { AuthSessionProvider } from '@/components/auth/auth-session-provider';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
const walletConnectProjectId =
  process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || undefined;
const supportedChains = [base, baseSepolia] as const;
const defaultChainId =
  process.env.NEXT_PUBLIC_ENVIRONMENT === 'production'
    ? base.id
    : baseSepolia.id;

const queryClient = new QueryClient();
const wagmiConfig = createConfig(
  getDefaultConfig({
    appName: 'InfraFund',
    chains: supportedChains,
    ssr: true,
    walletConnectProjectId,
  })
);

// Called by the Openfort SDK when it needs to create or restore the Shield
// encryption session for this user's embedded wallet. Runs server-side (our
// Next.js API route) so SHIELD_SECRET_KEY is never exposed to the client.
// Openfort passes this token to the Shield service as proof that our backend
// has authorised the key-share operation.
async function getEncryptionSession({
  accessToken,
  otpCode,
  userId,
}: {
  accessToken: string;
  otpCode?: string;
  userId: string;
}) {
  const response = await fetch('/api/auth/encryption-session', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ otp_code: otpCode, user_id: userId }),
  });
  const data: unknown = await response.json().catch(() => null);

  if (!response.ok) {
    const message =
      data && typeof data === 'object' && 'message' in data
        ? String(data.message)
        : 'Failed to create encryption session.';
    throw new Error(message);
  }

  if (
    !data ||
    typeof data !== 'object' ||
    !('session' in data) ||
    typeof data.session !== 'string'
  ) {
    throw new Error('Invalid encryption session response.');
  }

  return data.session;
}

// Workaround for an Openfort SDK bug (openfort-xyz/openfort-js#275):
// EmbeddedWalletApi.createIframe() appends the hidden iframe to document.body
// without setting a referrerpolicy attribute. Openfort's edge (Cloudflare)
// enforces an origin allowlist check via the Referer request header, so when
// the browser sends the iframe navigation without a Referer — which happens
// when no referrer policy is explicitly set — the response is 403 and the
// wallet never becomes READY.
//
// We cannot use a MutationObserver (fires after appendChild as a microtask)
// or a document-level Referrer-Policy header / <meta name="referrer"> tag
// because Chrome commits the iframe navigation's referrer policy synchronously
// at the appendChild call site — any attribute set after appendChild is too late.
//
// Instead we patch Node.prototype.appendChild so our code runs synchronously
// BEFORE the real appendChild, allowing us to set referrerpolicy="origin" while
// the element is still detached. The patch is scoped to the component lifetime
// and is narrowly targeted: it only acts on <iframe id="openfort-iframe">.
function OpenfortIframeFix() {
  useEffect(() => {
    const original = Node.prototype.appendChild;
    Node.prototype.appendChild = function <T extends Node>(child: T): T {
      if (
        child instanceof HTMLIFrameElement &&
        child.id === 'openfort-iframe' &&
        !child.referrerPolicy
      ) {
        child.referrerPolicy = 'origin';
      }
      return original.call(this, child) as T;
    };
    return () => {
      Node.prototype.appendChild = original;
    };
  }, []);
  return null;
}

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={publishableKey}
            walletConfig={{
              shieldPublishableKey,
              ethereum: {
                chainId: defaultChainId,
                ethereumFeeSponsorshipId:
                  process.env.NEXT_PUBLIC_POLICY_ID || undefined,
              },
              // connectOnLogin: false defers wallet creation until after our
              // backend has verified the user's eligibility (qualification
              // questionnaire). Without this flag the SDK would attempt to
              // create/connect the embedded wallet immediately on auth,
              // before we know whether the user is new or existing and
              // before the qualification gate has been passed.
              // AuthSessionProvider explicitly calls create() at the right
              // moment via createWalletIfNeeded().
              connectOnLogin: false,
              getEncryptionSession,
            }}
            uiConfig={{
              theme: 'midnight',
              mode: 'dark',
              authProviders: [AuthProvider.GOOGLE, AuthProvider.EMAIL_OTP],
              walletRecovery: { defaultMethod: RecoveryMethod.AUTOMATIC },
            }}
          >
            {/* OpenfortIframeFix must live inside OpenfortProvider so it mounts
                before AuthSessionProvider can trigger wallet creation. It patches
                appendChild for its own lifetime and is narrowly targeted. */}
            <OpenfortIframeFix />
            <AuthSessionProvider>{children}</AuthSessionProvider>
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  );
}

'use client';

// AuthSessionProvider bridges Openfort identity with our app session.
//
// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
// session (JWT + httpOnly refresh cookie), user profile, and the qualification
// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
// we call create() explicitly at the right moment.
//
// Status machine:
//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
//                 ↘ creating_wallet → authenticated   (existing user)
//                 ↘ error                             (any failure)
//
// New-user path (registration):
//   Openfort auth → check backend (exists: false) → qualification questionnaire
//   → backend exchange with role/type → createWalletIfNeeded → authenticated
//
// Existing-user path (login):
//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
//                                        ↘ no cookie → check backend (exists: true)
//                                          → backend exchange → createWalletIfNeeded
//
// createWalletIfNeeded always calls Openfort's create() to load the iframe and
// establish the embedded-wallet connection. For new users create() provisions
// the wallet; for returning users it reconnects to the existing one. Skipping
// this step for returning users leaves the wallet in [Not connected] state
// because the embedded-wallet iframe is never loaded (connectOnLogin: false).

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

type AuthStepId =
  | 'signing_in'
  | 'checking_account'
  | 'restoring_session'
  | 'creating_account'
  | 'loading_profile'
  | 'connecting_wallet'
  | 'setting_up_wallet';

type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';

export interface AuthProgressStep {
  id: AuthStepId;
  label: string;
  status: AuthStepStatus;
  errorMessage?: string;
}

interface AuthProgress {
  steps: AuthProgressStep[];
  isVisible: boolean;
}

const STEP_LABELS: Record<AuthStepId, string> = {
  signing_in: 'Authenticating with Openfort',
  checking_account: 'Checking your account',
  restoring_session: 'Restoring your session',
  creating_account: 'Creating your account',
  loading_profile: 'Loading your profile',
  connecting_wallet: 'Connecting your wallet',
  setting_up_wallet: 'Setting up your wallet',
};

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  deleteAccount: () => Promise<void>;
  logout: () => Promise<void>;
  authProgress: AuthProgress | null;
  dismissProgress: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (/not logged in|session/i.test(message)) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  if (/internal server error/i.test(message)) {
    return 'Our service is temporarily unavailable. Please try again in a moment.';
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
    null
  );
  const [retryCount, setRetryCount] = useState(0);
  const pathname = usePathname();
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
    walletStepId: 'connecting_wallet' | 'setting_up_wallet';
  } | null>(null);
  const previousAuthState = useRef(false);
  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
  // This prevents the useEffect from re-triggering bootstrap when callbacks are
  // recreated due to dependency changes mid-flow.
  const bootstrapAttemptKeyRef = useRef<string | null>(null);
  const [authProgress, setAuthProgress] = useState<AuthProgress | null>(null);

  const setStepPlan = useCallback((stepIds: AuthStepId[]) => {
    setAuthProgress({
      isVisible: true,
      steps: stepIds.map((id) => ({
        id,
        label: STEP_LABELS[id],
        status: 'pending',
      })),
    });
  }, []);

  const updateStep = useCallback(
    (id: AuthStepId, patch: Partial<AuthProgressStep>) => {
      setAuthProgress((current) => {
        if (!current) return current;
        const steps = current.steps.map((step) =>
          step.id === id ? { ...step, ...patch } : step
        );
        return { ...current, steps };
      });
    },
    []
  );

  const startStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'active', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'done', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStepsThrough = useCallback((id: AuthStepId) => {
    setAuthProgress((current) => {
      if (!current) return current;
      let reached = false;
      const steps = current.steps.map((step) => {
        if (reached) return step;
        const next: AuthProgressStep = { ...step, status: 'done' };
        if (step.id === id) reached = true;
        return next;
      });
      return { ...current, steps };
    });
  }, []);

  const failStep = useCallback(
    (id: AuthStepId, errorMessage: string) => {
      updateStep(id, { status: 'error', errorMessage });
    },
    [updateStep]
  );

  const showProgress = useCallback(() => {
    setAuthProgress((current) =>
      current ? { ...current, isVisible: true } : current
    );
  }, []);

  const hideProgress = useCallback(() => {
    setAuthProgress((current) =>
      current ? { ...current, isVisible: false } : current
    );
  }, []);

  const clearProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const dismissProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    setErrorCategory(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
    clearProgress();
  }, [clearProgress]);

  const commitUserFacingError = useCallback((raw: string) => {
    const userMessage = getUserFacingErrorMessage(raw);
    setError(userMessage);
    setErrorCategory(classifyError(raw));
    return userMessage;
  }, []);

  const baseReportExtras = useCallback(
    () => ({
      route: pathname ?? null,
      retryCount,
      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
    }),
    [openfortUserId, pathname, retryCount]
  );

  // Terminal success state: app session is fully established and the wallet
  // iframe is connected. Closes any Openfort modal still visible and resets
  // all transient state accumulated during the auth/onboarding flow.
  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      setErrorCategory(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  // Loads the Openfort embedded-wallet iframe and connects/creates the wallet,
  // then transitions to authenticated.
  //
  // Context when called: the backend session is already established (accessToken
  // and currentUser are valid). The Openfort SDK is authenticated. The only
  // remaining step is to load the hidden iframe so the wallet is usable.
  //
  // Why always call create(): connectOnLogin: false means the SDK never loads
  // the iframe automatically. create() is the correct call for both paths:
  //   - New user:      provisions the wallet and connects it via the iframe.
  //   - Existing user: reconnects to the existing wallet via the iframe.
  //                    The SDK's wallets[] array may already contain the wallet
  //                    (fetched from the Openfort API), but that does not mean
  //                    the iframe is loaded — without it the wallet is [Not
  //                    connected] and cannot sign transactions. Skipping create()
  //                    when wallets.length > 0 was the original bug causing
  //                    returning users to see [Not connected] on every login.
  const createWalletIfNeeded = useCallback(
    async (
      accessToken: string,
      currentUser: BackendMeResponse,
      walletStepId: 'connecting_wallet' | 'setting_up_wallet'
    ) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({
        accessToken,
        user: currentUser,
        walletStepId,
      });
      setStatus('creating_wallet');
      // walletStepId is decided by the caller: 'connecting_wallet' for
      // returning users, 'setting_up_wallet' for new users post-questionnaire.
      // We can't decide here from wallets.length because the SDK's wallets[]
      // is populated asynchronously and may still be empty at this point even
      // for returning users.
      startStep(walletStepId);

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        completeStep(walletStepId);
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        const rawMessage = getErrorMessage(walletError);
        reportError(walletError, {
          area: 'wallet',
          tags: { stage: 'create' },
          extra: {
            ...baseReportExtras(),
            hasExistingWallet: wallets.length > 0,
          },
        });
        const userMessage = commitUserFacingError(rawMessage);
        failStep(walletStepId, userMessage);
        setStatus('error');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      completeStep,
      create,
      failStep,
      finalizeAuthenticatedSession,
      startStep,
      wallets.length,
    ]
  );

  // Runs once per Openfort user identity (keyed on openfortUserId + retryCount).
  // Determines which path the user takes and drives them to createWalletIfNeeded.
  //
  // Priority order:
  //   1. Valid refresh cookie → restore the app session directly, skip Openfort
  //      token exchange (faster; avoids an extra round-trip to Openfort API).
  //   2. No refresh cookie, existing backend user → exchange Openfort token for
  //      app session.
  //   3. No backend user → show qualification questionnaire; wallet creation is
  //      deferred until completeOnboarding() succeeds.
  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    // Single fixed-length plan covering the union of both returning-user
    // sub-paths. The cookie short-circuit (Path 1) skips checking_account by
    // marking it 'done' alongside signing_in. The exchange path (Path 2) walks
    // through it normally. The list never grows or shrinks mid-flight.
    setStepPlan([
      'signing_in',
      'checking_account',
      'restoring_session',
      'loading_profile',
      'connecting_wallet',
    ]);
    completeStep('signing_in');

    try {
      // Path 1: try to restore an existing app session via the refresh cookie.
      // This is the fast path for page reloads and returning sessions.
      // The cookie attempt is silent (no UI change) — typically resolves in
      // <50 ms. Showing a spinner for it would tick step 3 active before
      // step 2, which looks out-of-order.
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        try {
          // Cookie path succeeded. Tick steps 2 and 3 in order: the cookie
          // makes both 'checking_account' (we know who you are) and
          // 'restoring_session' (your session is restored) effectively true.
          completeStep('checking_account');
          completeStep('restoring_session');
          startStep('loading_profile');
          const me = await getBackendMe(refreshedSession.access_token);
          completeStep('loading_profile');
          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
          // directly) so the embedded-wallet iframe is loaded and the wallet
          // becomes usable for signing — even on session restore.
          await createWalletIfNeeded(
            refreshedSession.access_token,
            me,
            'connecting_wallet'
          );
          return;
        } catch {
          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
          // Clear the stale cookie and fall through to Openfort re-auth. Reset
          // the steps we already ticked in the cookie branch so the exchange
          // path can re-walk them in order.
          await logoutBackendSession().catch(() => undefined);
          updateStep('checking_account', { status: 'pending' });
          updateStep('restoring_session', { status: 'pending' });
          updateStep('loading_profile', { status: 'pending' });
        }
      }

      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
      startStep('checking_account');
      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);
      completeStep('checking_account');

      if (!checkResponse.exists) {
        // Path 3: new user — hold the Openfort token and show the qualification
        // questionnaire. Wallet creation is deferred to completeOnboarding().
        // Hide the progress modal so the questionnaire is the only surface.
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        hideProgress();
        setStatus('needs_onboarding');
        return;
      }

      // Path 2: existing user — exchange the Openfort token for an app session.
      startStep('restoring_session');
      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      completeStep('restoring_session');

      startStep('loading_profile');
      const me = await getBackendMe(loginResponse.access_token);
      completeStep('loading_profile');

      await createWalletIfNeeded(
        loginResponse.access_token,
        me,
        'connecting_wallet'
      );
    } catch (sessionError) {
      reportError(sessionError, {
        area: 'auth',
        tags: { stage: 'bootstrap' },
        extra: baseReportExtras(),
      });
      setBackendAccessToken(null);
      setBackendUser(null);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      const userMessage = commitUserFacingError(getErrorMessage(sessionError));
      // Mark the currently-active step as failed so the modal points at the
      // step that broke. If nothing is active (shouldn't happen), this no-ops.
      setAuthProgress((current) => {
        if (!current) return current;
        const activeStep = current.steps.find((s) => s.status === 'active');
        if (!activeStep) return current;
        const steps = current.steps.map((s) =>
          s.id === activeStep.id
            ? {
                ...s,
                status: 'error' as AuthStepStatus,
                errorMessage: userMessage,
              }
            : s
        );
        return { ...current, steps };
      });
      setStatus('error');
    }
  }, [
    baseReportExtras,
    clearSession,
    closeOpenfortModal,
    commitUserFacingError,
    completeStep,
    createWalletIfNeeded,
    getAccessToken,
    hideProgress,
    openfortUserId,
    setStepPlan,
    startStep,
    updateStep,
  ]);

  // Called when the user submits the qualification questionnaire.
  // Context: status === 'needs_onboarding', pendingOnboardingAccessToken is set.
  // The Openfort token is still valid; no app session exists yet.
  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      // New-user post-questionnaire plan. signing_in and checking_account were
      // already completed during bootstrapSession; mark them done up front and
      // bring the progress modal back into view.
      setStepPlan([
        'signing_in',
        'checking_account',
        'creating_account',
        'loading_profile',
        'setting_up_wallet',
      ]);
      completeStepsThrough('checking_account');
      showProgress();

      try {
        startStep('creating_account');
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role,
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        completeStep('creating_account');

        startStep('loading_profile');
        const me = await getBackendMe(loginResponse.access_token);
        completeStep('loading_profile');

        await createWalletIfNeeded(
          loginResponse.access_token,
          me,
          'setting_up_wallet'
        );
      } catch (sessionError) {
        reportError(sessionError, {
          area: 'auth',
          tags: { stage: 'onboarding' },
          extra: baseReportExtras(),
        });
        const userMessage = commitUserFacingError(
          getErrorMessage(sessionError)
        );
        setAuthProgress((current) => {
          if (!current) return current;
          const activeStep = current.steps.find((s) => s.status === 'active');
          if (!activeStep) return current;
          const steps = current.steps.map((s) =>
            s.id === activeStep.id
              ? {
                  ...s,
                  status: 'error' as AuthStepStatus,
                  errorMessage: userMessage,
                }
              : s
          );
          return { ...current, steps };
        });
        setStatus('needs_onboarding');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      completeStep,
      completeStepsThrough,
      createWalletIfNeeded,
      pendingOnboardingAccessToken,
      setStepPlan,
      showProgress,
      startStep,
    ]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const logout = useCallback(async () => {
    setStatus('loading');
    setError(null);

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const deleteAccount = useCallback(async () => {
    setStatus('loading');
    setError(null);

    try {
      if (backendAccessToken) {
        await deleteBackendAccount(backendAccessToken);
      }
    } catch (deleteError) {
      reportError(deleteError, {
        area: 'auth',
        tags: { stage: 'delete-account' },
        extra: baseReportExtras(),
      });
      commitUserFacingError(getErrorMessage(deleteError));
      setStatus('authenticated');
      return;
    }

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [
    backendAccessToken,
    baseReportExtras,
    clearSession,
    commitUserFacingError,
    signOut,
  ]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user,
        pendingWalletCreation.walletStepId
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  // OAuth callback pre-emptive cover: when Openfort's redirect-based OAuth
  // returns the user to our app at `/?openfortAuthProviderUI=…`, the SDK's
  // ConnectModal auto-detects those params and reopens itself to run
  // ConnectWithOAuth (which calls storeCredentials). That UI flashes for a
  // few hundred ms before our bootstrap useEffect can run and close the
  // Openfort modal. Seeding authProgress here makes the task-103 modal
  // (z-[10001]) appear immediately on page load and cover the Openfort
  // ConnectWithOAuth page underneath. The signing_in step gets re-marked
  // done when bootstrapSession runs and overwrites the plan.
  useEffect(() => {
    if (typeof window === 'undefined') return;
    if (!window.location.search.includes('openfortAuthProviderUI')) return;
    setStepPlan([
      'signing_in',
      'checking_account',
      'restoring_session',
      'loading_profile',
      'connecting_wallet',
    ]);
    startStep('signing_in');
    // Eagerly close the Openfort modal too — defensive, since the SDK reopens
    // it on URL detection. Our bootstrap useEffect would do this once
    // isAuthenticated flips, but doing it here closes the gap.
    closeOpenfortModal();
    // Mount-only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Primary driver: react to Openfort auth state changes.
  // bootstrapAttemptKey deduplicate calls so we run bootstrap exactly once
  // per (user, retryCount) pair, even when the effect re-fires because a
  // callback was recreated due to dependency changes mid-flow.
  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
        currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;

    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
      return;
    }

    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;

    // Close the Openfort built-in modal immediately. Without this, the SDK's
    // CONNECTED page (the "Connected — Manage wallets" popup) stays visible
    // until finalizeAuthenticatedSession runs at the end of the bootstrap.
    closeOpenfortModal();

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    closeOpenfortModal,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  // Secondary driver: detect explicit sign-out. Openfort's own sign-out does
  // not call our logout endpoint, so we must revoke the app session cookie here.
  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
      logout,
      authProgress,
      dismissProgress,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
      logout,
      authProgress,
      dismissProgress,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

import 'server-only';

type ServerEnvFeature =
  | 'database'
  | 'auth'
  | 'openfort'
  | 'captcha'
  | 'email'
  | 'shield'
  | 'cron';

interface ServerEnv {
  app: {
    environment: string;
    isProduction: boolean;
  };
  database: {
    url?: string;
  };
  auth: {
    jwtSecret?: string;
    jwtIssuer?: string;
    jwtAudience: string;
  };
  openfort: {
    secretKey?: string;
    publishableKey?: string;
    baseUrl: string;
  };
  captcha: {
    googleSecret?: string;
  };
  email: {
    enabled: boolean;
    smtpHost?: string;
    smtpPort?: string;
    smtpUser?: string;
    smtpPassword?: string;
    smtpSender?: string;
    receiver?: string;
  };
  shield: {
    url: string;
    publishableKey?: string;
    secretKey?: string;
    encryptionShare?: string;
  };
  cron: {
    secret?: string;
  };
}

const requiredEnvByFeature: Record<ServerEnvFeature, string[]> = {
  database: ['DATABASE_URL'],
  auth: ['APP_JWT_SECRET'],
  openfort: ['OPENFORT_SECRET_KEY', 'OPENFORT_PUBLISHABLE_KEY'],
  captcha: ['RECAPTCHA_SECRET_KEY'],
  email: [
    'SMTP_HOST',
    'SMTP_PORT',
    'SMTP_PASSWORD',
    'SMTP_SENDER',
    'CONTACT_FORM_RECEIVER',
  ],
  shield: [
    'NEXT_PUBLIC_SHIELD_API_KEY',
    'SHIELD_SECRET_KEY',
    'SHIELD_ENCRYPTION_SHARE',
  ],
  cron: ['CRON_SECRET'],
};

let cachedEnv: ServerEnv | undefined;

function readOptionalString(name: string) {
  const value = process.env[name]?.trim();
  return value ? value : undefined;
}

function readBoolean(name: string, fallback = false) {
  const value = readOptionalString(name);

  if (!value) return fallback;

  return ['1', 'true', 'yes', 'on'].includes(value.toLowerCase());
}

export function getServerEnv() {
  if (cachedEnv) return cachedEnv;

  cachedEnv = {
    app: {
      environment:
        readOptionalString('NEXT_PUBLIC_ENVIRONMENT') ??
        readOptionalString('NODE_ENV') ??
        'development',
      isProduction: process.env.NODE_ENV === 'production',
    },
    database: {
      url: readOptionalString('DATABASE_URL'),
    },
    auth: {
      jwtSecret: readOptionalString('APP_JWT_SECRET'),
      jwtIssuer: readOptionalString('APP_JWT_ISSUER'),
      jwtAudience: readOptionalString('APP_JWT_AUDIENCE') ?? 'infrafund',
    },
    openfort: {
      secretKey: readOptionalString('OPENFORT_SECRET_KEY'),
      publishableKey: readOptionalString('OPENFORT_PUBLISHABLE_KEY'),
      baseUrl:
        readOptionalString('OPENFORT_BASE_URL') ?? 'https://api.openfort.io',
    },
    captcha: {
      googleSecret: readOptionalString('RECAPTCHA_SECRET_KEY'),
    },
    email: {
      enabled: readBoolean('CONTACT_FORM_EMAIL_ENABLED'),
      smtpHost: readOptionalString('SMTP_HOST'),
      smtpPort: readOptionalString('SMTP_PORT'),
      smtpUser: readOptionalString('SMTP_USER'),
      smtpPassword: readOptionalString('SMTP_PASSWORD'),
      smtpSender: readOptionalString('SMTP_SENDER'),
      receiver: readOptionalString('CONTACT_FORM_RECEIVER'),
    },
    shield: {
      url: readOptionalString('SHIELD_URL') ?? 'https://shield.openfort.io',
      publishableKey: readOptionalString('NEXT_PUBLIC_SHIELD_API_KEY'),
      secretKey: readOptionalString('SHIELD_SECRET_KEY'),
      encryptionShare: readOptionalString('SHIELD_ENCRYPTION_SHARE'),
    },
    cron: {
      secret: readOptionalString('CRON_SECRET'),
    },
  };

  return cachedEnv;
}

function findMissingServerEnv(features: ServerEnvFeature[]) {
  const env = getServerEnv();

  return features.flatMap((feature) => {
    if (feature === 'auth') {
      return env.auth.jwtSecret ? [] : requiredEnvByFeature.auth;
    }

    if (feature === 'openfort') {
      return [
        ...(env.openfort.secretKey ? [] : [requiredEnvByFeature.openfort[0]]),
        ...(env.openfort.publishableKey
          ? []
          : [requiredEnvByFeature.openfort[1]]),
      ];
    }

    if (feature === 'cron') {
      return env.cron.secret ? [] : requiredEnvByFeature.cron;
    }

    return requiredEnvByFeature[feature].filter(
      (name) => !readOptionalString(name)
    );
  });
}

export function requireServerEnv(features: ServerEnvFeature[]) {
  const missing = findMissingServerEnv(features);

  if (missing.length > 0) {
    throw new Error(
      `Missing server environment variables: ${missing.join(', ')}`
    );
  }

  return getServerEnv();
}

import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

export function deleteOpenfortUser(openfortUserId: string) {
  return getOpenfortClient().iam.users.delete(openfortUserId);
}

export function createOpenfortEncryptionSession() {
  const { shield } = requireServerEnv(['shield']);

  return getOpenfortClient().createEncryptionSession(
    shield.publishableKey!,
    shield.secretKey!,
    shield.encryptionShare!,
    shield.url
  );
}

import { NextRequest, NextResponse } from 'next/server';

import { requireBearerToken } from '@/server/auth/http';
import { ApiError, handleApiError } from '@/server/http';
import { logger } from '@/server/logger';
import {
  createOpenfortEncryptionSession,
  verifyOpenfortAccessToken,
} from '@/server/openfort/session';

export async function POST(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    const body = await request.json().catch(() => ({}));
    const requestedUserId =
      body && typeof body === 'object' && 'user_id' in body
        ? body.user_id
        : undefined;

    if (typeof requestedUserId !== 'string' || !requestedUserId.trim()) {
      throw new ApiError('BAD_REQUEST', 'Openfort user ID is required.');
    }

    const session = await verifyOpenfortAccessToken(accessToken);

    if (session.user.id !== requestedUserId) {
      throw new ApiError(
        'FORBIDDEN',
        'Openfort user mismatch for encryption session.'
      );
    }

    const encryptionSession = await createOpenfortEncryptionSession();

    return NextResponse.json({ session: encryptionSession });
  } catch (err) {
    logger.error({ err }, 'Encryption session error');
    return handleApiError(err);
  }
}

'use client';

import * as Sentry from '@sentry/nextjs';

type Severity = 'fatal' | 'error' | 'warning' | 'info';

interface ReportOptions {
  area: 'auth' | 'wallet' | 'openfort' | 'telemetry' | 'unknown';
  severity?: Severity;
  tags?: Record<string, string>;
  extra?: Record<string, unknown>;
  fingerprint?: string[];
}

export function isNoisyNetworkError(message: string | undefined | null) {
  if (!message) return false;
  return /failed to fetch|networkerror|load failed|analytics sdk/i.test(
    message
  );
}

export function reportError(error: unknown, options: ReportOptions) {
  const severity = options.severity ?? 'error';

  if (error instanceof Error && isNoisyNetworkError(error.message)) {
    Sentry.addBreadcrumb({
      category: options.area,
      message: error.message,
      level: 'warning',
      data: { ...options.extra },
    });
    return;
  }

  Sentry.captureException(error, {
    level: severity,
    tags: {
      area: options.area,
      ...options.tags,
    },
    extra: options.extra,
    fingerprint: options.fingerprint,
  });
}

import { NextRequest, NextResponse } from 'next/server';

import { requireBearerToken } from '@/server/auth/http';
import { ApiError, handleApiError } from '@/server/http';
import { logger } from '@/server/logger';
import {
  createOpenfortEncryptionSession,
  verifyOpenfortAccessToken,
} from '@/server/openfort/session';

export async function POST(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    const body = await request.json().catch(() => ({}));
    const requestedUserId =
      body && typeof body === 'object' && 'user_id' in body
        ? body.user_id
        : undefined;

    if (typeof requestedUserId !== 'string' || !requestedUserId.trim()) {
      throw new ApiError('BAD_REQUEST', 'Openfort user ID is required.');
    }

    const session = await verifyOpenfortAccessToken(accessToken);

    if (session.user.id !== requestedUserId) {
      throw new ApiError(
        'FORBIDDEN',
        'Openfort user mismatch for encryption session.'
      );
    }

    const encryptionSession = await createOpenfortEncryptionSession();

    return NextResponse.json({ session: encryptionSession });
  } catch (err) {
    logger.error({ err }, 'Encryption session error');
    return handleApiError(err);
  }
}

import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

export function deleteOpenfortUser(openfortUserId: string) {
  return getOpenfortClient().iam.users.delete(openfortUserId);
}

export function createOpenfortEncryptionSession() {
  const { shield } = requireServerEnv(['shield']);

  return getOpenfortClient().createEncryptionSession(
    shield.publishableKey!,
    shield.secretKey!,
    shield.encryptionShare!,
    shield.url
  );
}

'use client';

// AuthSessionProvider bridges Openfort identity with our app session.
//
// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
// session (JWT + httpOnly refresh cookie), user profile, and the qualification
// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
// we call create() explicitly at the right moment.
//
// Status machine:
//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
//                 ↘ creating_wallet → authenticated   (existing user)
//                 ↘ error                             (any failure)
//
// New-user path (registration):
//   Openfort auth → check backend (exists: false) → qualification questionnaire
//   → backend exchange with role/type → createWalletIfNeeded → authenticated
//
// Existing-user path (login):
//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
//                                        ↘ no cookie → check backend (exists: true)
//                                          → backend exchange → createWalletIfNeeded
//
// createWalletIfNeeded always calls Openfort's create() to load the iframe and
// establish the embedded-wallet connection. For new users create() provisions
// the wallet; for returning users it reconnects to the existing one. Skipping
// this step for returning users leaves the wallet in [Not connected] state
// because the embedded-wallet iframe is never loaded (connectOnLogin: false).

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

type AuthStepId =
  | 'signing_in'
  | 'checking_account'
  | 'restoring_session'
  | 'creating_account'
  | 'loading_profile'
  | 'connecting_wallet'
  | 'setting_up_wallet';

type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';

export interface AuthProgressStep {
  id: AuthStepId;
  label: string;
  status: AuthStepStatus;
  errorMessage?: string;
}

interface AuthProgress {
  steps: AuthProgressStep[];
  isVisible: boolean;
}

const STEP_LABELS: Record<AuthStepId, string> = {
  signing_in: 'Authenticating with Openfort',
  checking_account: 'Checking your account',
  restoring_session: 'Restoring your session',
  creating_account: 'Creating your account',
  loading_profile: 'Loading your profile',
  connecting_wallet: 'Connecting your wallet',
  setting_up_wallet: 'Setting up your wallet',
};

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  deleteAccount: () => Promise<void>;
  logout: () => Promise<void>;
  authProgress: AuthProgress | null;
  dismissProgress: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (/not logged in|session/i.test(message)) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  if (/internal server error/i.test(message)) {
    return 'Our service is temporarily unavailable. Please try again in a moment.';
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
    null
  );
  const [retryCount, setRetryCount] = useState(0);
  const pathname = usePathname();
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
    walletStepId: 'connecting_wallet' | 'setting_up_wallet';
  } | null>(null);
  const previousAuthState = useRef(false);
  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
  // This prevents the useEffect from re-triggering bootstrap when callbacks are
  // recreated due to dependency changes mid-flow.
  const bootstrapAttemptKeyRef = useRef<string | null>(null);
  const [authProgress, setAuthProgress] = useState<AuthProgress | null>(null);

  const setStepPlan = useCallback((stepIds: AuthStepId[]) => {
    setAuthProgress({
      isVisible: true,
      steps: stepIds.map((id) => ({
        id,
        label: STEP_LABELS[id],
        status: 'pending',
      })),
    });
  }, []);

  const updateStep = useCallback(
    (id: AuthStepId, patch: Partial<AuthProgressStep>) => {
      setAuthProgress((current) => {
        if (!current) return current;
        const steps = current.steps.map((step) =>
          step.id === id ? { ...step, ...patch } : step
        );
        return { ...current, steps };
      });
    },
    []
  );

  const startStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'active', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'done', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStepsThrough = useCallback((id: AuthStepId) => {
    setAuthProgress((current) => {
      if (!current) return current;
      let reached = false;
      const steps = current.steps.map((step) => {
        if (reached) return step;
        const next: AuthProgressStep = { ...step, status: 'done' };
        if (step.id === id) reached = true;
        return next;
      });
      return { ...current, steps };
    });
  }, []);

  const failStep = useCallback(
    (id: AuthStepId, errorMessage: string) => {
      updateStep(id, { status: 'error', errorMessage });
    },
    [updateStep]
  );

  const showProgress = useCallback(() => {
    setAuthProgress((current) =>
      current ? { ...current, isVisible: true } : current
    );
  }, []);

  const hideProgress = useCallback(() => {
    setAuthProgress((current) =>
      current ? { ...current, isVisible: false } : current
    );
  }, []);

  const clearProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const dismissProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    setErrorCategory(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
    clearProgress();
  }, [clearProgress]);

  const commitUserFacingError = useCallback((raw: string) => {
    const userMessage = getUserFacingErrorMessage(raw);
    setError(userMessage);
    setErrorCategory(classifyError(raw));
    return userMessage;
  }, []);

  const baseReportExtras = useCallback(
    () => ({
      route: pathname ?? null,
      retryCount,
      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
    }),
    [openfortUserId, pathname, retryCount]
  );

  // Terminal success state: app session is fully established and the wallet
  // iframe is connected. Closes any Openfort modal still visible and resets
  // all transient state accumulated during the auth/onboarding flow.
  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      setErrorCategory(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  // Loads the Openfort embedded-wallet iframe and connects/creates the wallet,
  // then transitions to authenticated.
  //
  // Context when called: the backend session is already established (accessToken
  // and currentUser are valid). The Openfort SDK is authenticated. The only
  // remaining step is to load the hidden iframe so the wallet is usable.
  //
  // Why always call create(): connectOnLogin: false means the SDK never loads
  // the iframe automatically. create() is the correct call for both paths:
  //   - New user:      provisions the wallet and connects it via the iframe.
  //   - Existing user: reconnects to the existing wallet via the iframe.
  //                    The SDK's wallets[] array may already contain the wallet
  //                    (fetched from the Openfort API), but that does not mean
  //                    the iframe is loaded — without it the wallet is [Not
  //                    connected] and cannot sign transactions. Skipping create()
  //                    when wallets.length > 0 was the original bug causing
  //                    returning users to see [Not connected] on every login.
  const createWalletIfNeeded = useCallback(
    async (
      accessToken: string,
      currentUser: BackendMeResponse,
      walletStepId: 'connecting_wallet' | 'setting_up_wallet'
    ) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({
        accessToken,
        user: currentUser,
        walletStepId,
      });
      setStatus('creating_wallet');
      // walletStepId is decided by the caller: 'connecting_wallet' for
      // returning users, 'setting_up_wallet' for new users post-questionnaire.
      // We can't decide here from wallets.length because the SDK's wallets[]
      // is populated asynchronously and may still be empty at this point even
      // for returning users.
      startStep(walletStepId);

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        completeStep(walletStepId);
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        const rawMessage = getErrorMessage(walletError);
        reportError(walletError, {
          area: 'wallet',
          tags: { stage: 'create' },
          extra: {
            ...baseReportExtras(),
            hasExistingWallet: wallets.length > 0,
          },
        });
        const userMessage = commitUserFacingError(rawMessage);
        failStep(walletStepId, userMessage);
        setStatus('error');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      completeStep,
      create,
      failStep,
      finalizeAuthenticatedSession,
      startStep,
      wallets.length,
    ]
  );

  // Runs once per Openfort user identity (keyed on openfortUserId + retryCount).
  // Determines which path the user takes and drives them to createWalletIfNeeded.
  //
  // Priority order:
  //   1. Valid refresh cookie → restore the app session directly, skip Openfort
  //      token exchange (faster; avoids an extra round-trip to Openfort API).
  //   2. No refresh cookie, existing backend user → exchange Openfort token for
  //      app session.
  //   3. No backend user → show qualification questionnaire; wallet creation is
  //      deferred until completeOnboarding() succeeds.
  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    // Single fixed-length plan covering the union of both returning-user
    // sub-paths. The cookie short-circuit (Path 1) skips checking_account by
    // marking it 'done' alongside signing_in. The exchange path (Path 2) walks
    // through it normally. The list never grows or shrinks mid-flight.
    setStepPlan([
      'signing_in',
      'checking_account',
      'restoring_session',
      'loading_profile',
      'connecting_wallet',
    ]);
    completeStep('signing_in');

    try {
      // Path 1: try to restore an existing app session via the refresh cookie.
      // This is the fast path for page reloads and returning sessions.
      // The cookie attempt is silent (no UI change) — typically resolves in
      // <50 ms. Showing a spinner for it would tick step 3 active before
      // step 2, which looks out-of-order.
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        try {
          // Cookie path succeeded. Tick steps 2 and 3 in order: the cookie
          // makes both 'checking_account' (we know who you are) and
          // 'restoring_session' (your session is restored) effectively true.
          completeStep('checking_account');
          completeStep('restoring_session');
          startStep('loading_profile');
          const me = await getBackendMe(refreshedSession.access_token);
          completeStep('loading_profile');
          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
          // directly) so the embedded-wallet iframe is loaded and the wallet
          // becomes usable for signing — even on session restore.
          await createWalletIfNeeded(
            refreshedSession.access_token,
            me,
            'connecting_wallet'
          );
          return;
        } catch {
          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
          // Clear the stale cookie and fall through to Openfort re-auth. Reset
          // the steps we already ticked in the cookie branch so the exchange
          // path can re-walk them in order.
          await logoutBackendSession().catch(() => undefined);
          updateStep('checking_account', { status: 'pending' });
          updateStep('restoring_session', { status: 'pending' });
          updateStep('loading_profile', { status: 'pending' });
        }
      }

      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
      startStep('checking_account');
      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);
      completeStep('checking_account');

      if (!checkResponse.exists) {
        // Path 3: new user — hold the Openfort token and show the qualification
        // questionnaire. Wallet creation is deferred to completeOnboarding().
        // Hide the progress modal so the questionnaire is the only surface.
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        hideProgress();
        setStatus('needs_onboarding');
        return;
      }

      // Path 2: existing user — exchange the Openfort token for an app session.
      startStep('restoring_session');
      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      completeStep('restoring_session');

      startStep('loading_profile');
      const me = await getBackendMe(loginResponse.access_token);
      completeStep('loading_profile');

      await createWalletIfNeeded(
        loginResponse.access_token,
        me,
        'connecting_wallet'
      );
    } catch (sessionError) {
      reportError(sessionError, {
        area: 'auth',
        tags: { stage: 'bootstrap' },
        extra: baseReportExtras(),
      });
      setBackendAccessToken(null);
      setBackendUser(null);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      const userMessage = commitUserFacingError(getErrorMessage(sessionError));
      // Mark the currently-active step as failed so the modal points at the
      // step that broke. If nothing is active (shouldn't happen), this no-ops.
      setAuthProgress((current) => {
        if (!current) return current;
        const activeStep = current.steps.find((s) => s.status === 'active');
        if (!activeStep) return current;
        const steps = current.steps.map((s) =>
          s.id === activeStep.id
            ? {
                ...s,
                status: 'error' as AuthStepStatus,
                errorMessage: userMessage,
              }
            : s
        );
        return { ...current, steps };
      });
      setStatus('error');
    }
  }, [
    baseReportExtras,
    clearSession,
    closeOpenfortModal,
    commitUserFacingError,
    completeStep,
    createWalletIfNeeded,
    getAccessToken,
    hideProgress,
    openfortUserId,
    setStepPlan,
    startStep,
    updateStep,
  ]);

  // Called when the user submits the qualification questionnaire.
  // Context: status === 'needs_onboarding', pendingOnboardingAccessToken is set.
  // The Openfort token is still valid; no app session exists yet.
  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      // New-user post-questionnaire plan. signing_in and checking_account were
      // already completed during bootstrapSession; mark them done up front and
      // bring the progress modal back into view.
      setStepPlan([
        'signing_in',
        'checking_account',
        'creating_account',
        'loading_profile',
        'setting_up_wallet',
      ]);
      completeStepsThrough('checking_account');
      showProgress();

      try {
        startStep('creating_account');
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role,
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        completeStep('creating_account');

        startStep('loading_profile');
        const me = await getBackendMe(loginResponse.access_token);
        completeStep('loading_profile');

        await createWalletIfNeeded(
          loginResponse.access_token,
          me,
          'setting_up_wallet'
        );
      } catch (sessionError) {
        reportError(sessionError, {
          area: 'auth',
          tags: { stage: 'onboarding' },
          extra: baseReportExtras(),
        });
        const userMessage = commitUserFacingError(
          getErrorMessage(sessionError)
        );
        setAuthProgress((current) => {
          if (!current) return current;
          const activeStep = current.steps.find((s) => s.status === 'active');
          if (!activeStep) return current;
          const steps = current.steps.map((s) =>
            s.id === activeStep.id
              ? {
                  ...s,
                  status: 'error' as AuthStepStatus,
                  errorMessage: userMessage,
                }
              : s
          );
          return { ...current, steps };
        });
        setStatus('needs_onboarding');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      completeStep,
      completeStepsThrough,
      createWalletIfNeeded,
      pendingOnboardingAccessToken,
      setStepPlan,
      showProgress,
      startStep,
    ]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const logout = useCallback(async () => {
    setStatus('loading');
    setError(null);

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const deleteAccount = useCallback(async () => {
    setStatus('loading');
    setError(null);

    try {
      if (backendAccessToken) {
        await deleteBackendAccount(backendAccessToken);
      }
    } catch (deleteError) {
      reportError(deleteError, {
        area: 'auth',
        tags: { stage: 'delete-account' },
        extra: baseReportExtras(),
      });
      commitUserFacingError(getErrorMessage(deleteError));
      setStatus('authenticated');
      return;
    }

    await Promise.allSettled([
      logoutBackendSession().catch(() => undefined),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [
    backendAccessToken,
    baseReportExtras,
    clearSession,
    commitUserFacingError,
    signOut,
  ]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user,
        pendingWalletCreation.walletStepId
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  // OAuth callback pre-emptive cover: when Openfort's redirect-based OAuth
  // returns the user to our app at `/?openfortAuthProviderUI=…`, the SDK's
  // ConnectModal auto-detects those params and reopens itself to run
  // ConnectWithOAuth (which calls storeCredentials). That UI flashes for a
  // few hundred ms before our bootstrap useEffect can run and close the
  // Openfort modal. Seeding authProgress here makes the task-103 modal
  // (z-[10001]) appear immediately on page load and cover the Openfort
  // ConnectWithOAuth page underneath. The signing_in step gets re-marked
  // done when bootstrapSession runs and overwrites the plan.
  useEffect(() => {
    if (typeof window === 'undefined') return;
    if (!window.location.search.includes('openfortAuthProviderUI')) return;
    setStepPlan([
      'signing_in',
      'checking_account',
      'restoring_session',
      'loading_profile',
      'connecting_wallet',
    ]);
    startStep('signing_in');
    // Eagerly close the Openfort modal too — defensive, since the SDK reopens
    // it on URL detection. Our bootstrap useEffect would do this once
    // isAuthenticated flips, but doing it here closes the gap.
    closeOpenfortModal();
    // Mount-only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Primary driver: react to Openfort auth state changes.
  // bootstrapAttemptKey deduplicate calls so we run bootstrap exactly once
  // per (user, retryCount) pair, even when the effect re-fires because a
  // callback was recreated due to dependency changes mid-flow.
  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
        currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;

    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
      return;
    }

    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;

    // Close the Openfort built-in modal immediately. Without this, the SDK's
    // CONNECTED page (the "Connected — Manage wallets" popup) stays visible
    // until finalizeAuthenticatedSession runs at the end of the bootstrap.
    closeOpenfortModal();

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    closeOpenfortModal,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  // Secondary driver: detect explicit sign-out. Openfort's own sign-out does
  // not call our logout endpoint, so we must revoke the app session cookie here.
  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
      logout,
      authProgress,
      dismissProgress,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      errorCategory,
      retry,
      deleteAccount,
      logout,
      authProgress,
      dismissProgress,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

import 'server-only';

import { NextResponse } from 'next/server';

export type ApiErrorCode =
  | 'BAD_REQUEST'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'CONFLICT'
  | 'TOO_MANY_REQUESTS'
  | 'VALIDATION_ERROR'
  | 'INTERNAL_SERVER_ERROR'
  | 'SERVICE_UNAVAILABLE';

export interface ApiErrorBody {
  code: ApiErrorCode;
  message: string;
  detail?: string;
  fields?: Record<string, string>;
}

export class ApiError extends Error {
  readonly code: ApiErrorCode;
  readonly status: number;
  readonly detail?: string;
  readonly fields?: Record<string, string>;

  constructor(
    code: ApiErrorCode,
    message: string,
    options: {
      status?: number;
      detail?: string;
      fields?: Record<string, string>;
      cause?: unknown;
    } = {}
  ) {
    super(message, { cause: options.cause });
    this.name = 'ApiError';
    this.code = code;
    this.status = options.status ?? statusByCode[code];
    this.detail = options.detail;
    this.fields = options.fields;
  }
}

const statusByCode: Record<ApiErrorCode, number> = {
  BAD_REQUEST: 400,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  TOO_MANY_REQUESTS: 429,
  VALIDATION_ERROR: 422,
  INTERNAL_SERVER_ERROR: 500,
  SERVICE_UNAVAILABLE: 503,
};

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError;
}

export function toApiErrorBody(error: ApiError): ApiErrorBody {
  return {
    code: error.code,
    message: error.message,
    ...(error.detail ? { detail: error.detail } : {}),
    ...(error.fields ? { fields: error.fields } : {}),
  };
}

export function jsonError(error: ApiError) {
  return NextResponse.json(toApiErrorBody(error), { status: error.status });
}

export function internalServerError() {
  return new ApiError('INTERNAL_SERVER_ERROR', 'Internal server error');
}

'use client';

// AuthSessionProvider bridges Openfort identity with our app session.
//
// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
// session (JWT + httpOnly refresh cookie), user profile, and the qualification
// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
// we call create() explicitly at the right moment.
//
// Status machine:
//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
//                 ↘ creating_wallet → authenticated   (existing user)
//                 ↘ error                             (any failure)
//
// New-user path (registration):
//   Openfort auth → check backend (exists: false) → qualification questionnaire
//   → backend exchange with role/type → createWalletIfNeeded → authenticated
//
// Existing-user path (login):
//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
//                                        ↘ no cookie → check backend (exists: true)
//                                          → backend exchange → createWalletIfNeeded
//
// createWalletIfNeeded always calls Openfort's create() to load the iframe and
// establish the embedded-wallet connection. For new users create() provisions
// the wallet; for returning users it reconnects to the existing one. Skipping
// this step for returning users leaves the wallet in [Not connected] state
// because the embedded-wallet iframe is never loaded (connectOnLogin: false).

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

type AuthStepId =
  | 'signing_in'
  | 'checking_account'
  | 'restoring_session'
  | 'creating_account'
  | 'loading_profile'
  | 'connecting_wallet'
  | 'setting_up_wallet';

type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';

export interface AuthProgressStep {
  id: AuthStepId;
  label: string;
  status: AuthStepStatus;
  errorMessage?: string;
}

interface AuthProgress {
  steps: AuthProgressStep[];
  isVisible: boolean;
}

const STEP_LABELS: Record<AuthStepId, string> = {
  signing_in: 'Authenticating with Openfort',
  checking_account: 'Checking your account',
  restoring_session: 'Restoring your session',
  creating_account: 'Creating your account',
  loading_profile: 'Loading your profile',
  connecting_wallet: 'Connecting your wallet',
  setting_up_wallet: 'Setting up your wallet',
};

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  deleteAccount: () => Promise<void>;
  logout: () => Promise<void>;
  authProgress: AuthProgress | null;
  dismissProgress: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (/not logged in|session/i.test(message)) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  if (/internal server error/i.test(message)) {
    return 'Our service is temporarily unavailable. Please try again in a moment.';
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
    null
  );
  const [retryCount, setRetryCount] = useState(0);
  const pathname = usePathname();
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
    walletStepId: 'connecting_wallet' | 'setting_up_wallet';
  } | null>(null);
  const previousAuthState = useRef(false);
  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
  // This prevents the useEffect from re-triggering bootstrap when callbacks are
  // recreated due to dependency changes mid-flow.
  const bootstrapAttemptKeyRef = useRef<string | null>(null);
  const [authProgress, setAuthProgress] = useState<AuthProgress | null>(null);

  const setStepPlan = useCallback((stepIds: AuthStepId[]) => {
    setAuthProgress({
      isVisible: true,
      steps: stepIds.map((id) => ({
        id,
        label: STEP_LABELS[id],
        status: 'pending',
      })),
    });
  }, []);

  const updateStep = useCallback(
    (id: AuthStepId, patch: Partial<AuthProgressStep>) => {
      setAuthProgress((current) => {
        if (!current) return current;
        const steps = current.steps.map((step) =>
          step.id === id ? { ...step, ...patch } : step
        );
        return { ...current, steps };
      });
    },
    []
  );

  const startStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'active', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStep = useCallback(
    (id: AuthStepId) => {
      updateStep(id, { status: 'done', errorMessage: undefined });
    },
    [updateStep]
  );

  const completeStepsThrough = useCallback((id: AuthStepId) => {
    setAuthProgress((current) => {
      if (!current) return current;
      let reached = false;
      const steps = current.steps.map((step) => {
        if (reached) return step;
        const next: AuthProgressStep = { ...step, status: 'done' };
        if (step.id === id) reached = true;
        return next;
      });
      return { ...current, steps };
    });
  }, []);

  const failStep = useCallback(
    (id: AuthStepId, errorMessage: string) => {
      updateStep(id, { status: 'error', errorMessage });
    },
    [updateStep]
  );

  const showProgress = useCallback(() => {

<system-reminder>[Showing lines 1-260 of 864 total lines]</system-reminder>

    setAuthProgress((current) =>
      current ? { ...current, isVisible: true } : current
    );
  }, []);

  const hideProgress = useCallback(() => {
    setAuthProgress((current) =>
      current ? { ...current, isVisible: false } : current
    );
  }, []);

  const clearProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const dismissProgress = useCallback(() => {
    setAuthProgress(null);
  }, []);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    setErrorCategory(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
    clearProgress();
  }, [clearProgress]);

  const commitUserFacingError = useCallback((raw: string) => {
    const userMessage = getUserFacingErrorMessage(raw);
    setError(userMessage);
    setErrorCategory(classifyError(raw));
    return userMessage;
  }, []);

  const baseReportExtras = useCallback(
    () => ({
      route: pathname ?? null,
      retryCount,
      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
    }),
    [openfortUserId, pathname, retryCount]
  );

  // Terminal success state: app session is fully established and the wallet
  // iframe is connected. Closes any Openfort modal still visible and resets
  // all transient state accumulated during the auth/onboarding flow.
  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      setErrorCategory(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  // Loads the Openfort embedded-wallet iframe and connects/creates the wallet,
  // then transitions to authenticated.
  //
  // Context when called: the backend session is already established (accessToken
  // and currentUser are valid). The Openfort SDK is authenticated. The only
  // remaining step is to load the hidden iframe so the wallet is usable.
  //
  // Why always call create(): connectOnLogin: false means the SDK never loads
  // the iframe automatically. create() is the correct call for both paths:
  //   - New user:      provisions the wallet and connects it via the iframe.
  //   - Existing user: reconnects to the existing wallet via the iframe.
  //                    The SDK's wallets[] array may already contain the wallet
  //                    (fetched from the Openfort API), but that does not mean
  //                    the iframe is loaded — without it the wallet is [Not
  //                    connected] and cannot sign transactions. Skipping create()
  //                    when wallets.length > 0 was the original bug causing
  //                    returning users to see [Not connected] on every login.
  const createWalletIfNeeded = useCallback(
    async (
      accessToken: string,
      currentUser: BackendMeResponse,
      walletStepId: 'connecting_wallet' | 'setting_up_wallet'
    ) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({
        accessToken,
        user: currentUser,
        walletStepId,
      });
      setStatus('creating_wallet');
      // walletStepId is decided by the caller: 'connecting_wallet' for
      // returning users, 'setting_up_wallet' for new users post-questionnaire.
      // We can't decide here from wallets.length because the SDK's wallets[]
      // is populated asynchronously and may still be empty at this point even
      // for returning users.
      startStep(walletStepId);

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        completeStep(walletStepId);
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        const rawMessage = getErrorMessage(walletError);
        reportError(walletError, {
          area: 'wallet',
          tags: { stage: 'create' },
          extra: {
            ...baseReportExtras(),
            hasExistingWallet: wallets.length > 0,
          },
        });
        const userMessage = commitUserFacingError(rawMessage);
        failStep(walletStepId, userMessage);
        setStatus('error');
      }
    },
    [
      baseReportExtras,
      commitUserFacingError,
      completeStep,
      create,
      failStep,
      finalizeAuthenticatedSession,
      startStep,
      wallets.length,
    ]
  );

  // Runs once per Openfort user identity (keyed on openfortUserId + retryCount).
  // Determines which path the user takes and drives them to createWalletIfNeeded.
  //
  // Priority order:
  //   1. Valid refresh cookie → restore the app session directly, skip Openfort
  //      token exchange (faster; avoids an extra round-trip to Openfort API).
  //   2. No refresh cookie, existing backend user → exchange Openfort token for
  //      app session.
  //   3. No backend user → show qualification questionnaire; wallet creation is
  //      deferred until completeOnboarding() succeeds.
  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    // Single fixed-length plan covering the union of both returning-user
    // sub-paths. The cookie short-circuit (Path 1) skips checking_account by
    // marking it 'done' alongside signing_in. The exchange path (Path 2) walks
    // through it normally. The list never grows or shrinks mid-flight.
    setStepPlan([
      'signing_in',
      'checking_account',
      'restoring_session',
      'loading_profile',
      'connecting_wallet',
    ]);
    completeStep('signing_in');

    try {
      // Path 1: try to restore an existing app session via the refresh cookie.
      // This is the fast path for page reloads and returning sessions.
      // The cookie attempt is silent (no UI change) — typically resolves in
      // <50 ms. Showing a spinner for it would tick step 3 active before
      // step 2, which looks out-of-order.
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        try {
          // Cookie path succeeded. Tick steps 2 and 3 in order: the cookie
          // makes both 'checking_account' (we know who you are) and
          // 'restoring_session' (your session is restored) effectively true.
          completeStep('checking_account');
          completeStep('restoring_session');
          startStep('loading_profile');
          const me = await getBackendMe(refreshedSession.access_token);
          completeStep('loading_profile');
          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
          // directly) so the embedded-wallet iframe is loaded and the wallet
          // becomes usable for signing — even on session restore.
          await createWalletIfNeeded(
            refreshedSession.access_token,
            me,
            'connecting_wallet'
          );
          return;
        } catch {
          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
          // Clear the stale cookie and fall through to Openfort re-auth. Reset
          // the steps we already ticked in the cookie branch so the exchange
          // path can re-walk them in order.
          await logoutBackendSession().catch(() => undefined);
          updateStep('checking_account', { status: 'pending' });
          updateStep('restoring_session', { status: 'pending' });
          updateStep('loading_profile', { status: 'pending' });
        }
      }

      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
      startStep('checking_account');
      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);
      completeStep('checking_account');

      if (!checkResponse.exists) {
        // Path 3: new user — hold the Openfort token and show the qualification
        // questionnaire. Wallet creation is deferred to completeOnboarding().
        // Hide the progress modal so the questionnaire is the only surface.
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        hideProgress();
        setStatus('needs_onboarding');
        return;
      }

      // Path 2: existing user — exchange the Openfort token for an app session.
      startStep('restoring_session');
      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      completeStep('restoring_session');

      startStep('loading_profile');
      const me = await getBackendMe(loginResponse.access_token);
      completeStep('loading_profile');

      await createWalletIfNeeded(
        loginResponse.access_token,
        me,
        'connecting_wallet'
      );
    } catch (sessionError) {
      reportError(sessionError, {
        area: 'auth',
        tags: { stage: 'bootstrap' },
        extra: baseReportExtras(),
      });
      setBackendAccessToken(null);
      setBackendUser(null);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      const userMessage = commitUserFacingError(getErrorMessage(sessionError));
      // Mark the currently-active step as failed so the modal points at the
      // step that broke. If nothing is active (shouldn't happen), this no-ops.
      setAuthProgress((current) => {
        if (!current) return current;
        const activeStep = current.steps.find((s) => s.status === 'active');
        if (!activeStep) return current;
        const steps = current.steps.map((s) =>
          s.id === activeStep.id
            ? {
                ...s,
                status: 'error' as AuthStepStatus,
                errorMessage: userMessage,
              }
            : s
        );
        return { ...current, steps };
      });
      setStatus('error');
    }
  }, [
    baseReportExtras,
    clearSession,
    closeOpenfortModal,
    commitUserFacingError,
    completeStep,
    createWalletIfNeeded,
    getAccessToken,
    hideProgress,
    openfortUserId,
    setStepPlan,
    startStep,
    updateStep,
  ]);

  // Called when the user submits the qualification questionnaire.
  // Context: status === 'needs_onboarding', pendingOnboardingAccessToken is set.
