async function findOrCreateUser(
  input: OpenfortExchangeInput,
  session: VerifiedOpenfortSession
) {
  const existingUser = await findUserByOpenfortId(session.user.id);

  if (existingUser) {
    return { user: existingUser, created: false };
  }

  assertNewUserPayload(input);

  try {
    return {
      user: await createUser(buildUserRecord(input, session)),
      created: true,
    };
  } catch (error) {
    if (isUserUniqueConstraintError(error)) {
      const recoveredUser = await findUserByOpenfortId(session.user.id);

      if (recoveredUser) {
        return { user: recoveredUser, created: false };
      }

      throw new ApiError(
        'CONFLICT',
        'User already exists.',
        {
          detail:
            'A user record was created while onboarding was still in progress. Please sign in again to continue.',
        }
      );
    }

    throw error;
  }
}

